rich-text.schema:
interface RichTextDocument {
  readonly id: string;
  readonly profile: string;
  readonly type: "doc";
  readonly content: ReadonlyArray<RichTextBlockNode | RichTextExtensionNode>;
}

type RichTextBlockNode =
  | RichTextParagraph
  | RichTextHeading
  | RichTextBlockquote
  | RichTextCodeBlock
  | RichTextBulletList
  | RichTextOrderedList;

interface RichTextText { readonly id: string; readonly type: "text"; readonly text: string; readonly marks: ReadonlyArray<RichTextMark> }
interface RichTextHardBreak { readonly id: string; readonly type: "hardBreak" }
interface RichTextParagraph { readonly id: string; readonly type: "paragraph"; readonly content: ReadonlyArray<RichTextText | RichTextHardBreak> }
interface RichTextHeading { readonly id: string; readonly type: "heading"; readonly attrs: { readonly level: 1 | 2 | 3 | 4 | 5 | 6 }; readonly content: ReadonlyArray<RichTextText | RichTextHardBreak> }
interface RichTextBlockquote { readonly id: string; readonly type: "blockquote"; readonly content: ReadonlyArray<RichTextBlockNode> }
interface RichTextCodeBlock { readonly id: string; readonly type: "codeBlock"; readonly attrs: { readonly language: string | null }; readonly content: readonly [] | readonly [RichTextText] }
interface RichTextListItem { readonly id: string; readonly type: "listItem"; readonly content: ReadonlyArray<RichTextBlockNode> }
interface RichTextBulletList { readonly id: string; readonly type: "bulletList"; readonly content: ReadonlyArray<RichTextListItem> }
interface RichTextOrderedList { readonly id: string; readonly type: "orderedList"; readonly attrs: { readonly start: number }; readonly content: ReadonlyArray<RichTextListItem> }
type RichTextExtensionNode = { readonly id: string; readonly type: `${string}/${string}`; readonly attrs?: Readonly<Record<string, JSONValue>>; readonly content?: ReadonlyArray<RichTextNode> };

