type AnnotationSelector =
  | { readonly type: "point"; readonly x: number; readonly y: number }
  | { readonly type: "rectangle"; readonly x: number; readonly y: number; readonly width: number; readonly height: number }
  | { readonly type: "path"; readonly points: ReadonlyArray<{ x: number; y: number }> }
